import type { OccasionTemplate } from './types.ts'

/**
 * Timezone: Asia/Riyadh (UTC+3, no DST). Event dates are stored as YYYY-MM-DD
 * calendar dates in Riyadh, plus optional local time HH:mm.
 *
 * Gregorian national days are stable. Hijri-linked dates are stored only for
 * published years (2026–2027) from commonly cited Umm al-Qura civil dates —
 * they are not generated by a homemade Hijri formula for later years.
 */
export const APP_TIMEZONE = 'Asia/Riyadh'

export function riyadhYmd(date = new Date()) {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: APP_TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(date)
}

export function daysUntil(ymd: string, from = riyadhYmd()) {
  const a = Date.parse(`${from}T00:00:00+03:00`)
  const b = Date.parse(`${ymd}T00:00:00+03:00`)
  return Math.round((b - a) / 86400000)
}

export function addDays(ymd: string, days: number) {
  return riyadhYmd(new Date(Date.parse(`${ymd}T00:00:00+03:00`) + days * 86400000))
}

